{
  "meta": {
    "name": "Online Learning Platform",
    "description": "An online learning platform where instructors publish courses and students enroll, complete lessons, and provide reviews, with a freemium model offering access to paid courses and certificates via subscription."
  },
  "entities": [
    {
      "name": "Course",
      "ownable": true,
      "fields": [
        {
          "name": "title",
          "type": "string",
          "required": true
        },
        {
          "name": "description",
          "type": "text"
        },
        {
          "name": "price",
          "type": "number",
          "default": 0
        },
        {
          "name": "isFree",
          "type": "boolean",
          "default": true
        }
      ],
      "relations": [
        {
          "name": "lessons",
          "kind": "oneToMany",
          "target": "Lesson"
        },
        {
          "name": "reviews",
          "kind": "oneToMany",
          "target": "Review"
        }
      ]
    },
    {
      "name": "Lesson",
      "fields": [
        {
          "name": "title",
          "type": "string",
          "required": true
        },
        {
          "name": "videoUrl",
          "type": "url"
        }
      ],
      "relations": [
        {
          "name": "course",
          "kind": "manyToOne",
          "target": "Course",
          "required": true
        }
      ]
    },
    {
      "name": "Enrollment",
      "ownable": true,
      "fields": [
        {
          "name": "enrollmentDate",
          "type": "datetime",
          "default": "now()"
        }
      ],
      "relations": [
        {
          "name": "course",
          "kind": "manyToOne",
          "target": "Course",
          "required": true
        }
      ]
    },
    {
      "name": "LessonCompletion",
      "ownable": true,
      "fields": [
        {
          "name": "completionDate",
          "type": "datetime",
          "default": "now()"
        }
      ],
      "relations": [
        {
          "name": "lesson",
          "kind": "manyToOne",
          "target": "Lesson",
          "required": true
        }
      ]
    },
    {
      "name": "Review",
      "ownable": true,
      "fields": [
        {
          "name": "rating",
          "type": "integer",
          "required": true
        },
        {
          "name": "comment",
          "type": "text"
        }
      ],
      "relations": [
        {
          "name": "course",
          "kind": "manyToOne",
          "target": "Course",
          "required": true
        }
      ]
    }
  ],
  "roles": [
    {
      "name": "instructor",
      "description": "Can publish courses and view student progress."
    },
    {
      "name": "student",
      "description": "Can enroll in courses, mark lessons complete, rate and review.",
      "isDefault": true
    },
    {
      "name": "admin",
      "description": "Platform administrator."
    }
  ],
  "permissions": [
    {
      "role": "instructor",
      "entity": "Course",
      "actions": ["create", "read", "update", "delete"],
      "scope": "own"
    },
    {
      "role": "instructor",
      "entity": "Lesson",
      "actions": ["create", "read", "update", "delete"],
      "scope": "all"
    },
    {
      "role": "instructor",
      "entity": "Enrollment",
      "actions": ["read"],
      "scope": "all"
    },
    {
      "role": "instructor",
      "entity": "LessonCompletion",
      "actions": ["read"],
      "scope": "all"
    },
    {
      "role": "student",
      "entity": "Course",
      "actions": ["read"],
      "scope": "all",
      "requiresPlan": "premium"
    },
    {
      "role": "student",
      "entity": "Lesson",
      "actions": ["read"],
      "scope": "all",
      "requiresPlan": "premium"
    },
    {
      "role": "student",
      "entity": "Enrollment",
      "actions": ["create", "read", "delete"],
      "scope": "own"
    },
    {
      "role": "student",
      "entity": "LessonCompletion",
      "actions": ["create", "read", "update"],
      "scope": "own"
    },
    {
      "role": "student",
      "entity": "Review",
      "actions": ["create", "read", "update", "delete"],
      "scope": "own"
    },
    {
      "role": "admin",
      "entity": "Course",
      "actions": ["create", "read", "update", "delete"],
      "scope": "all"
    },
    {
      "role": "admin",
      "entity": "Lesson",
      "actions": ["create", "read", "update", "delete"],
      "scope": "all"
    },
    {
      "role": "admin",
      "entity": "Enrollment",
      "actions": ["read", "delete"],
      "scope": "all"
    },
    {
      "role": "admin",
      "entity": "LessonCompletion",
      "actions": ["read", "delete"],
      "scope": "all"
    },
    {
      "role": "admin",
      "entity": "Review",
      "actions": ["read", "delete"],
      "scope": "all"
    }
  ],
  "pages": [
    {
      "name": "Courses",
      "route": "/courses",
      "type": "list",
      "entity": "Course",
      "access": ["instructor", "student", "admin"]
    },
    {
      "name": "Course Detail",
      "route": "/courses/:id",
      "type": "detail",
      "entity": "Course",
      "access": ["instructor", "student", "admin"]
    },
    {
      "name": "New Course",
      "route": "/courses/new",
      "type": "form",
      "entity": "Course",
      "access": ["instructor", "admin"]
    },
    {
      "name": "Edit Course",
      "route": "/courses/:id/edit",
      "type": "form",
      "entity": "Course",
      "access": ["instructor", "admin"]
    },
    {
      "name": "Lessons",
      "route": "/lessons",
      "type": "list",
      "entity": "Lesson",
      "access": ["instructor", "admin"]
    },
    {
      "name": "New Lesson",
      "route": "/lessons/new",
      "type": "form",
      "entity": "Lesson",
      "access": ["instructor", "admin"]
    },
    {
      "name": "Edit Lesson",
      "route": "/lessons/:id/edit",
      "type": "form",
      "entity": "Lesson",
      "access": ["instructor", "admin"]
    },
    {
      "name": "Enrollments",
      "route": "/enrollments",
      "type": "list",
      "entity": "Enrollment",
      "access": ["student", "admin"]
    },
    {
      "name": "My Courses",
      "route": "/my-courses",
      "type": "list",
      "entity": "Course",
      "access": ["student"],
      "fields": ["title", "description", "price"]
    },
    {
      "name": "Instructor Dashboard",
      "route": "/dashboard/instructor",
      "type": "dashboard",
      "access": ["instructor"],
      "widgets": [
        {
          "type": "stat",
          "label": "Total Students Enrolled",
          "entity": "Enrollment",
          "metric": "count"
        },
        {
          "type": "stat",
          "label": "Total Lessons Completed",
          "entity": "LessonCompletion",
          "metric": "count"
        }
      ]
    },
    {
      "name": "Student Dashboard",
      "route": "/dashboard/student",
      "type": "dashboard",
      "access": ["student"],
      "widgets": [
        {
          "type": "table",
          "label": "My Enrollments",
          "entity": "Enrollment",
          "fields": ["course.title", "enrollmentDate"]
        }
      ]
    },
    {
      "name": "Admin Dashboard",
      "route": "/dashboard/admin",
      "type": "dashboard",
      "access": ["admin"],
      "widgets": [
        {
          "type": "stat",
          "label": "Total Courses",
          "entity": "Course",
          "metric": "count"
        },
        {
          "type": "stat",
          "label": "Total Students",
          "entity": "Enrollment",
          "metric": "count"
        }
      ]
    },
    {
      "name": "Premium Content",
      "route": "/premium",
      "type": "custom",
      "access": ["student"],
      "requiresPlan": "premium"
    },
    {
      "name": "Certificates",
      "route": "/certificates",
      "type": "custom",
      "access": ["student"],
      "requiresPlan": "premium"
    }
  ],
  "plans": [
    {
      "name": "free",
      "price": 0,
      "isDefault": true,
      "features": ["access_free_courses", "rate_review_courses"]
    },
    {
      "name": "premium",
      "price": 10,
      "interval": "month",
      "features": ["access_paid_courses", "completion_certificates"]
    }
  ],
  "businessRules": [
    {
      "type": "plan_gate",
      "id": "premiumContentGate",
      "requiresPlan": "premium",
      "gates": {
        "pages": ["Premium Content", "Certificates"],
        "features": ["access_paid_courses", "completion_certificates"]
      }
    },
    {
      "type": "ownership",
      "id": "courseOwnership",
      "entity": "Course"
    },
    {
      "type": "ownership",
      "id": "enrollmentOwnership",
      "entity": "Enrollment"
    },
    {
      "type": "ownership",
      "id": "lessonCompletionOwnership",
      "entity": "LessonCompletion"
    },
    {
      "type": "ownership",
      "id": "reviewOwnership",
      "entity": "Review"
    }
  ],
  "auth": {
    "strategy": "email_password",
    "requireAuth": true
  }
}
